export type RicosDocument = {
  /** Array of nodes representing content elements, such as `ParagraphNode` or `HeadingNode`. */
  nodes: RicosDocumentNode[];
  /** Information about the Ricos document itself, such as its version. Only relevant when building the Ricos document using the [Ricos playground](https:/ricos.dev), in which case it is auto-generated. */
  metadata?: Metadata;
  /** Includes styling to be applied throughout the Ricos document for the specified node types. For example, you can define general styling for `headerOne`, and then override some of the properties separately for a specific header. */
  documentStyle?: DocumentStyle;
};
export type NodeStyle = {
  /** The top padding value in pixels. */
  paddingTop?: string;
  /** The bottom padding value in pixels. */
  paddingBottom?: string;
  backgroundColor?: string;
};
/**
 * Sets a default styling for specific node types throughout the entire Ricos Document. For example, you can set the text color for all Heading 1 nodes.
 * You can override the styling of specific Text nodes separately using [decorations](#decorations).
 */
export type DocumentStyle = {
  /** Style for the H1 nodes. */
  headerOne?: TextNodeStyle;
  /** Style for the H2 nodes. */
  headerTwo?: TextNodeStyle;
  /** Style for the H3 nodes. */
  headerThree?: TextNodeStyle;
  /** Style for the H4 nodes. */
  headerFour?: TextNodeStyle;
  /** Style for the H5 nodes. */
  headerFive?: TextNodeStyle;
  /** Style for the H6 nodes. */
  headerSix?: TextNodeStyle;
  /** Style for the paragraph nodes. */
  paragraph?: TextNodeStyle;
  /** Style for the block quote nodes. */
  blockquote?: TextNodeStyle;
  /** Style for the codeblock nodes. */
  codeBlock?: TextNodeStyle;
};
export type TextNodeStyle = {
  decorations?: Decoration[];
  /**
   * Node style, such as padding.
   *  **Note:** This node requires the [lineSpacing](#plugins) plugin to be enabled.
   */
  nodeStyle?: NodeStyle;
  /** Text line height. */
  lineHeight?: string;
};
export type Metadata = {
  /** Ricos document version. */
  version?: number;
  id?: any;
  createdTimestamp?: any;
  updatedTimestamp?: any;
};
/** Node animation, discriminated by `type`. `VIEW` animations play while the node is in view; `POINTER` animations follow the visitor's mouse. The kinds are mutually exclusive by construction — additional kinds (scroll-driven) may be added in the future. */
export type Animation = Animation_View | Animation_Pointer;
export type Animation_Type = 'VIEW' | 'POINTER';

export const Animation_Type = {
  VIEW: 'VIEW',
  POINTER: 'POINTER',
} as const;

/** Animations that play while the node is in view. At least one of `entrance` or `loop` should be set — an empty `VIEW` is treated as no animation. */
export type Animation_View = {
  /**
   * Animation kind.
   *  Must be `VIEW`.
   */
  type: 'VIEW';
  /** Entrance animation, played once when the node first enters the viewport. */
  entrance?: EntranceAnimation;
  /** Looping animation, repeated indefinitely while the node is on the page. When combined with `entrance`, the loop starts after the entrance finishes. */
  loop?: LoopAnimation;
};
/** Animations driven by the visitor's mouse position — the node continuously reacts as the pointer moves. Mutually exclusive with `VIEW` animations by construction. */
export type Animation_Pointer = {
  /**
   * Animation kind.
   *  Must be `POINTER`.
   */
  type: 'POINTER';
  /** The mouse effect, discriminated by `type`. */
  effect: PointerEffect;
  /** How quickly the node settles toward the pointer, in milliseconds (the editor's velocity control). When omitted, the effect's own tuned default is used. */
  transitionDuration?: number;
};
/** Entrance animation configuration: the effect to play and its timing options. */
export type EntranceAnimation = {
  /** The entrance effect, discriminated by `type`. */
  effect: EntranceEffect;
  /** Effect duration in milliseconds. When omitted, the effect's own tuned default is used — each effect has a different one. */
  duration?: number;
  /** Delay before the effect starts, in milliseconds. */
  delay?: number;
};
/** Entrance effect, discriminated by `type`. Each effect exposes only its own parameters; all parameters are optional and fall back to tuned defaults. */
export type EntranceEffect =
  | EntranceEffect_Fade
  | EntranceEffect_Arc
  | EntranceEffect_Blur
  | EntranceEffect_Bounce
  | EntranceEffect_Drop
  | EntranceEffect_Expand
  | EntranceEffect_Flip
  | EntranceEffect_Float
  | EntranceEffect_Fold
  | EntranceEffect_Glide
  | EntranceEffect_Reveal
  | EntranceEffect_Shape
  | EntranceEffect_Shutters
  | EntranceEffect_Slide
  | EntranceEffect_Spin
  | EntranceEffect_Tilt
  | EntranceEffect_Turn
  | EntranceEffect_Wink;
export type EntranceEffect_Type =
  | 'FADE'
  | 'ARC'
  | 'BLUR'
  | 'BOUNCE'
  | 'DROP'
  | 'EXPAND'
  | 'FLIP'
  | 'FLOAT'
  | 'FOLD'
  | 'GLIDE'
  | 'REVEAL'
  | 'SHAPE'
  | 'SHUTTERS'
  | 'SLIDE'
  | 'SPIN'
  | 'TILT'
  | 'TURN'
  | 'WINK';

export const EntranceEffect_Type = {
  FADE: 'FADE',
  ARC: 'ARC',
  BLUR: 'BLUR',
  BOUNCE: 'BOUNCE',
  DROP: 'DROP',
  EXPAND: 'EXPAND',
  FLIP: 'FLIP',
  FLOAT: 'FLOAT',
  FOLD: 'FOLD',
  GLIDE: 'GLIDE',
  REVEAL: 'REVEAL',
  SHAPE: 'SHAPE',
  SHUTTERS: 'SHUTTERS',
  SLIDE: 'SLIDE',
  SPIN: 'SPIN',
  TILT: 'TILT',
  TURN: 'TURN',
  WINK: 'WINK',
} as const;

/** Fades in smoothly from fully transparent to fully opaque. */
export type EntranceEffect_Fade = {
  /**
   * Effect type.
   *  Must be `FADE`.
   */
  type: 'FADE';
};
/** Enters along a 3D arc path, rotating into view with depth motion. */
export type EntranceEffect_Arc = {
  /**
   * Effect type.
   *  Must be `ARC`.
   */
  type: 'ARC';
  /** Direction the element arcs in from. Defaults to `LEFT`. */
  direction?: Animation_Direction;
  /** Motion style. Defaults to `MODERATE`. */
  easing?: Animation_Easing;
};
/** Transitions from blurred to sharp while fading in. */
export type EntranceEffect_Blur = {
  /**
   * Effect type.
   *  Must be `BLUR`.
   */
  type: 'BLUR';
  /** Motion style. Defaults to `GENTLE`. */
  easing?: Animation_Easing;
};
/** Bounces into place from a direction with an elastic multi-step curve. */
export type EntranceEffect_Bounce = {
  /**
   * Effect type.
   *  Must be `BOUNCE`.
   */
  type: 'BOUNCE';
  /** Direction the element bounces in from. `CENTER` bounces in place, with no travel. Defaults to `TOP`. */
  direction?: EntranceEffect_Bounce_Direction;
  /** Motion style. Defaults to `GENTLE`. */
  easing?: Animation_Easing;
};
export type EntranceEffect_Bounce_Direction = 'LEFT' | 'RIGHT' | 'TOP' | 'BOTTOM' | 'CENTER';

export const EntranceEffect_Bounce_Direction = {
  LEFT: 'LEFT',
  RIGHT: 'RIGHT',
  TOP: 'TOP',
  BOTTOM: 'BOTTOM',
  CENTER: 'CENTER',
} as const;

/** Shrinks down from a larger size to its final scale. */
export type EntranceEffect_Drop = {
  /**
   * Effect type.
   *  Must be `DROP`.
   */
  type: 'DROP';
  /** Motion style. Defaults to `GENTLE`. */
  easing?: Animation_Easing;
};
/** Expands from a point in a given direction, scaling from small to full size with a fade-in. */
export type EntranceEffect_Expand = {
  /**
   * Effect type.
   *  Must be `EXPAND`.
   */
  type: 'EXPAND';
  /** Direction the element travels in from while expanding. `CENTER` expands in place, with no travel. Defaults to `CENTER`. */
  direction?: Animation_RadialDirection;
  /** Motion style. Defaults to `GENTLE`. */
  easing?: Animation_Easing;
};
/** Flips into view with a 3D rotation around the X or Y axis. */
export type EntranceEffect_Flip = {
  /**
   * Effect type.
   *  Must be `FLIP`.
   */
  type: 'FLIP';
  /** Direction the element flips in from. Defaults to `BOTTOM`. */
  direction?: Animation_Direction;
  /** Motion style. Defaults to `GENTLE`. */
  easing?: Animation_Easing;
};
/** Drifts gently into place from a direction with a fade-in. */
export type EntranceEffect_Float = {
  /**
   * Effect type.
   *  Must be `FLOAT`.
   */
  type: 'FLOAT';
  /** Direction the element floats in from. Defaults to `BOTTOM`. */
  direction?: Animation_Direction;
};
/** Unfolds from an edge, rotating around an axis at the edge as if hinged. */
export type EntranceEffect_Fold = {
  /**
   * Effect type.
   *  Must be `FOLD`.
   */
  type: 'FOLD';
  /** Edge the element unfolds from. Defaults to `TOP`. */
  direction?: Animation_Direction;
  /** Motion style. Defaults to `INTENSE`. */
  easing?: Animation_Easing;
};
/** Glides in smoothly from off-screen along a direction. */
export type EntranceEffect_Glide = {
  /**
   * Effect type.
   *  Must be `GLIDE`.
   */
  type: 'GLIDE';
  /** Direction the element glides in from, including the diagonals. Defaults to `BOTTOM`. */
  direction?: EntranceEffect_Glide_Direction;
  /** Motion style. Defaults to `GENTLE`. */
  easing?: Animation_Easing;
};
export type EntranceEffect_Glide_Direction =
  | 'RIGHT'
  | 'TOP_RIGHT'
  | 'TOP'
  | 'TOP_LEFT'
  | 'LEFT'
  | 'BOTTOM_LEFT'
  | 'BOTTOM'
  | 'BOTTOM_RIGHT';

export const EntranceEffect_Glide_Direction = {
  RIGHT: 'RIGHT',
  TOP_RIGHT: 'TOP_RIGHT',
  TOP: 'TOP',
  TOP_LEFT: 'TOP_LEFT',
  LEFT: 'LEFT',
  BOTTOM_LEFT: 'BOTTOM_LEFT',
  BOTTOM: 'BOTTOM',
  BOTTOM_RIGHT: 'BOTTOM_RIGHT',
} as const;

/** Progressively revealed by an expanding clip-path from one edge. */
export type EntranceEffect_Reveal = {
  /**
   * Effect type.
   *  Must be `REVEAL`.
   */
  type: 'REVEAL';
  /** Edge the reveal starts from. Defaults to `BOTTOM`. */
  direction?: Animation_Direction;
};
/** Appears through an expanding geometric clip-path shape. */
export type EntranceEffect_Shape = {
  /**
   * Effect type.
   *  Must be `SHAPE`.
   */
  type: 'SHAPE';
  /** Clip-path shape. Defaults to `CIRCLE`. */
  shape?: EntranceEffect_Shape_ClipShape;
};
export type EntranceEffect_Shape_ClipShape = 'ELLIPSE' | 'CIRCLE' | 'RECTANGLE' | 'DIAMOND';

export const EntranceEffect_Shape_ClipShape = {
  ELLIPSE: 'ELLIPSE',
  CIRCLE: 'CIRCLE',
  RECTANGLE: 'RECTANGLE',
  DIAMOND: 'DIAMOND',
} as const;

/** Revealed through multiple shutter-like strips that open in sequence. */
export type EntranceEffect_Shutters = {
  /**
   * Effect type.
   *  Must be `SHUTTERS`.
   */
  type: 'SHUTTERS';
  /** Direction the shutters open toward. Defaults to `RIGHT`. */
  direction?: Animation_Direction;
};
/** Slides in from one side while being revealed with a clip-path mask. */
export type EntranceEffect_Slide = {
  /**
   * Effect type.
   *  Must be `SLIDE`.
   */
  type: 'SLIDE';
  /** Direction the element slides in from. Defaults to `BOTTOM`. */
  direction?: Animation_Direction;
  /** Motion style. Defaults to `INTENSE`. */
  easing?: Animation_Easing;
};
/** Spins into view while scaling from small to full size. */
export type EntranceEffect_Spin = {
  /**
   * Effect type.
   *  Must be `SPIN`.
   */
  type: 'SPIN';
  /** Rotation direction. Defaults to `CLOCKWISE`. */
  direction?: Animation_SpinDirection;
  /** Motion style. Defaults to `MODERATE`. */
  easing?: Animation_Easing;
};
/** Tilts in from the side with 3D rotation and a clip-path reveal. */
export type EntranceEffect_Tilt = {
  /**
   * Effect type.
   *  Must be `TILT`.
   */
  type: 'TILT';
  /** Side the element tilts in from. Defaults to `LEFT`. */
  direction?: Animation_SideDirection;
};
/** Rotates into view around a corner pivot point. */
export type EntranceEffect_Turn = {
  /**
   * Effect type.
   *  Must be `TURN`.
   */
  type: 'TURN';
  /** Corner pivot the element turns around. Defaults to `BOTTOM_LEFT`. */
  direction?: Animation_CornerDirection;
  /** Motion style. Defaults to `INTENSE`. */
  easing?: Animation_Easing;
};
/** Winks into view by expanding from its horizontal or vertical center, while being revealed with a clip-path. */
export type EntranceEffect_Wink = {
  /**
   * Effect type.
   *  Must be `WINK`.
   */
  type: 'WINK';
  /** Axis the wink expands along. Defaults to `VERTICAL`. */
  direction?: Animation_Orientation;
};
/** Looping animation configuration: the effect to repeat and its timing options. The effect repeats indefinitely while the node is on the page. */
export type LoopAnimation = {
  /** The looping effect, discriminated by `type`. */
  effect: LoopEffect;
  /** Duration of a single iteration in milliseconds. When omitted, the effect's own tuned default is used — each effect has a different one. */
  duration?: number;
  /** Pause between iterations in milliseconds. */
  iterationDelay?: number;
};
/** Looping effect, discriminated by `type`. Each effect exposes only its own parameters; all parameters are optional and fall back to tuned defaults. */
export type LoopEffect =
  | LoopEffect_Bounce
  | LoopEffect_Breathe
  | LoopEffect_Cross
  | LoopEffect_Flash
  | LoopEffect_Flip
  | LoopEffect_Fold
  | LoopEffect_Jello
  | LoopEffect_Poke
  | LoopEffect_Pulse
  | LoopEffect_Rubber
  | LoopEffect_Spin
  | LoopEffect_Swing
  | LoopEffect_Wiggle;
export type LoopEffect_Type =
  | 'BOUNCE'
  | 'BREATHE'
  | 'CROSS'
  | 'FLASH'
  | 'FLIP'
  | 'FOLD'
  | 'JELLO'
  | 'POKE'
  | 'PULSE'
  | 'RUBBER'
  | 'SPIN'
  | 'SWING'
  | 'WIGGLE';

export const LoopEffect_Type = {
  BOUNCE: 'BOUNCE',
  BREATHE: 'BREATHE',
  CROSS: 'CROSS',
  FLASH: 'FLASH',
  FLIP: 'FLIP',
  FOLD: 'FOLD',
  JELLO: 'JELLO',
  POKE: 'POKE',
  PULSE: 'PULSE',
  RUBBER: 'RUBBER',
  SPIN: 'SPIN',
  SWING: 'SWING',
  WIGGLE: 'WIGGLE',
} as const;

/** Bounces up and down in place with an elastic multi-step curve. */
export type LoopEffect_Bounce = {
  /**
   * Effect type.
   *  Must be `BOUNCE`.
   */
  type: 'BOUNCE';
  /** Motion style. Defaults to `GENTLE`. */
  easing?: Animation_Easing;
};
/** Scales gently in and out along an axis, as if breathing. */
export type LoopEffect_Breathe = {
  /**
   * Effect type.
   *  Must be `BREATHE`.
   */
  type: 'BREATHE';
  /** Axis the breathing motion travels along. `CENTER` breathes in place with a 3D depth motion instead. Defaults to `VERTICAL`. */
  direction?: LoopEffect_Breathe_Direction;
};
export type LoopEffect_Breathe_Direction = 'HORIZONTAL' | 'VERTICAL' | 'CENTER';

export const LoopEffect_Breathe_Direction = {
  HORIZONTAL: 'HORIZONTAL',
  VERTICAL: 'VERTICAL',
  CENTER: 'CENTER',
} as const;

/** Drifts across its container toward one side, then re-enters from the opposite side. */
export type LoopEffect_Cross = {
  /**
   * Effect type.
   *  Must be `CROSS`.
   */
  type: 'CROSS';
  /** Side the element drifts toward. Defaults to `RIGHT`. */
  direction?: Animation_SideDirection;
};
/** Fades out to fully transparent and back in. */
export type LoopEffect_Flash = {
  /**
   * Effect type.
   *  Must be `FLASH`.
   */
  type: 'FLASH';
};
/** Rotates a full turn around its horizontal or vertical axis in 3D. */
export type LoopEffect_Flip = {
  /**
   * Effect type.
   *  Must be `FLIP`.
   */
  type: 'FLIP';
  /** Axis the element flips around. Defaults to `HORIZONTAL`. */
  direction?: Animation_Orientation;
  /** Motion style. Defaults to `GENTLE`. */
  easing?: Animation_Easing;
};
/** Folds back and forth around a hinged edge in 3D. */
export type LoopEffect_Fold = {
  /**
   * Effect type.
   *  Must be `FOLD`.
   */
  type: 'FOLD';
  /** Edge the element is hinged on. Defaults to `TOP`. */
  direction?: Animation_Direction;
  /** Motion style. Defaults to `MODERATE`. */
  easing?: Animation_Easing;
};
/** Wobbles with a jelly-like skew that settles gradually. */
export type LoopEffect_Jello = {
  /**
   * Effect type.
   *  Must be `JELLO`.
   */
  type: 'JELLO';
  /** Motion style. Defaults to `GENTLE`. */
  easing?: Animation_Easing;
};
/** Nudges repeatedly toward a direction and springs back. */
export type LoopEffect_Poke = {
  /**
   * Effect type.
   *  Must be `POKE`.
   */
  type: 'POKE';
  /** Direction the element pokes toward. Defaults to `RIGHT`. */
  direction?: Animation_Direction;
  /** Motion style. Defaults to `MODERATE`. */
  easing?: Animation_Easing;
};
/** Scales up and back down rhythmically. */
export type LoopEffect_Pulse = {
  /**
   * Effect type.
   *  Must be `PULSE`.
   */
  type: 'PULSE';
  /** Motion style. Defaults to `GENTLE`. */
  easing?: Animation_Easing;
};
/** Stretches and squashes like a rubber band. */
export type LoopEffect_Rubber = {
  /**
   * Effect type.
   *  Must be `RUBBER`.
   */
  type: 'RUBBER';
  /** Motion style. Defaults to `GENTLE`. */
  easing?: Animation_Easing;
};
/** Rotates continuously around its center. */
export type LoopEffect_Spin = {
  /**
   * Effect type.
   *  Must be `SPIN`.
   */
  type: 'SPIN';
  /** Rotation direction. Defaults to `CLOCKWISE`. */
  direction?: Animation_SpinDirection;
  /** Motion style. Defaults to `GENTLE`. */
  easing?: Animation_Easing;
};
/** Swings back and forth around an edge pivot, like a hanging sign. */
export type LoopEffect_Swing = {
  /**
   * Effect type.
   *  Must be `SWING`.
   */
  type: 'SWING';
  /** Edge the element swings from. Defaults to `TOP`. */
  direction?: Animation_Direction;
  /** Motion style. Defaults to `GENTLE`. */
  easing?: Animation_Easing;
};
/** Rocks side to side with a quick, accumulating rotation. */
export type LoopEffect_Wiggle = {
  /**
   * Effect type.
   *  Must be `WIGGLE`.
   */
  type: 'WIGGLE';
  /** Motion style. Defaults to `GENTLE`. */
  easing?: Animation_Easing;
};
/** Mouse effect, discriminated by `type`. Each effect exposes only its own parameters; all parameters are optional and fall back to tuned defaults. */
export type PointerEffect =
  | PointerEffect_Airy
  | PointerEffect_Blob
  | PointerEffect_Blur
  | PointerEffect_Scale
  | PointerEffect_Skew
  | PointerEffect_Swivel
  | PointerEffect_Tilt3d
  | PointerEffect_Track
  | PointerEffect_Track3d;
export type PointerEffect_Type =
  | 'AIRY'
  | 'BLOB'
  | 'BLUR'
  | 'SCALE'
  | 'SKEW'
  | 'SWIVEL'
  | 'TILT_3D'
  | 'TRACK'
  | 'TRACK_3D';

export const PointerEffect_Type = {
  AIRY: 'AIRY',
  BLOB: 'BLOB',
  BLUR: 'BLUR',
  SCALE: 'SCALE',
  SKEW: 'SKEW',
  SWIVEL: 'SWIVEL',
  TILT_3D: 'TILT_3D',
  TRACK: 'TRACK',
  TRACK_3D: 'TRACK_3D',
} as const;

